'use strict';

const VERSION='BXH-LADDER-V1-LINEAR';
const TIERS=Object.freeze([
  {name:'未定級',min:0},{name:'青銅',min:1},{name:'白銀',min:100},
  {name:'黃金',min:300},{name:'白金',min:600},{name:'鑽石',min:1100},
  {name:'大師',min:1800},{name:'宗師',min:2800}
